tool_input.old_string:
requestObjectsFormatter(row) {
  const values = this.getRequestObjectValues(row._requestObjects)
  if (!values.length) return ''
  if (values.includes('public')) {
    return this.getRequestObjectLabel('public')
  }
  return values.map(this.getRequestObjectLabel).join('、')
},

tool_input.new_string:
requestObjectsFormatter(row) {
  const values = this.getRequestObjectValues(row._requestObjects)
  // 报修分类的诉求对象固定为“物业/物管会/业委会”，与编辑弹窗保持一致；
  // 历史数据里可能仍存有 public 等旧值，列表按当前规则展示，避免列表与详情不一致
  if (this.isRepairCategory(row)) {
    return this.getRequestObjectLabel('property')
  }
  if (!values.length) return ''
  if (values.includes('public')) {
    return this.getRequestObjectLabel('public')
  }
  return values.map(this.getRequestObjectLabel).join('、')
},
isRepairCategory(row) {
  const categoryType = row._categoryType ?? row.categoryType ?? row.type
  return String(categoryType ?? '') === '2'
},
